$workflows["alert-to-pagerduty"] = @'
{"name":"Quantive: Critical Alert → PagerDuty","nodes":[{"parameters":{},"id":"webhook","name":"Webhook","type":"n8n-nodes-base.webhook","typeVersion":2,"position":[250,300],"webhookId":"quantive-pagerduty"},{"parameters":{"conditions":{"options":{"caseSensitive":true},"conditions":[{"id":"is-critical","leftValue":"={{$json.severity}}","rightValue":"CRITICAL","operator":{"type":"string","operation":"equal"}}],"combinator":"and"}},"id":"if-critical","name":"Is Critical?","type":"n8n-nodes-base.if","typeVersion":2,"position":[450,300]},{"parameters":{"url":"https://events.pagerduty.com/v2/enqueue","sendBody":true,"bodyParameters":{"parameters":[{"name":"routing_key","value":"={{$parameter.routingKey}}"},{"name":"event_action","value":"trigger"},{"name":"payload","value":"={\"summary\":\"Quantive: {{$json.title}}\",\"source\":\"Quantive\",\"severity\":\"critical\",\"component\":\"Transaction Monitoring\",\"group\":\"Compliance\",\"class\":\"Alert\",\"custom_details\":{\"alertId\":\"{{$json.id}}\",\"reasonCode\":\"{{$json.reasonCode}}\",\"txHash\":\"{{$json.transaction.txHash}}\",\"chain\":\"{{$json.transaction.chain}}\",\"value\":\"{{$json.transaction.value}}\"}}"},{"name":"dedup_key","value":"=quantive-{{$json.id}}"}],"options":{}},"options":{}},"id":"create-pd","name":"Create PD Incident","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[650,200]},{"parameters":{"conditions":{"options":{"caseSensitive":true},"conditions":[{"id":"not-ack","leftValue":"={{$json.status}}","rightValue":"ACKNOWLEDGED","operator":{"type":"string","operation":"notEqual"}}],"combinator":"and"},"waitTime":1800},"id":"wait-ack","name":"Wait 30m for Ack","type":"n8n-nodes-base.wait","typeVersion":1,"position":[650,400]},{"parameters":{"url":"http://localhost:4000/api/v1/auth/login","sendBody":true,"bodyParameters":{"parameters":[{"name":"email","value":"={{$parameter.quantiveEmail}}"},{"name":"password","value":"={{$parameter.quantivePassword}}"}],"options":{}},"options":{}},"id":"login","name":"Quantive Login","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[850,400]},{"parameters":{"url":"=http://localhost:4000/api/v1/alerts/{{$node[\"Webhook\"].json.id}}/status","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendBody":true,"method":"PATCH","bodyParameters":{"parameters":[{"name":"status","value":"ESCALATED"}],"options":{}},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{$json.data.accessToken}}"}],"options":{}},"options":{}},"id":"escalate","name":"Escalate in Quantive","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1050,400]},{"parameters":{"url":"https://events.pagerduty.com/v2/enqueue","sendBody":true,"bodyParameters":{"parameters":[{"name":"routing_key","value":"={{$parameter.routingKey}}"},{"name":"event_action","value":"escalate"},{"name":"dedup_key","value":"=quantive-{{$node[\"Webhook\"].json.id}}"}],"options":{}},"options":{}},"id":"escalate-pd","name":"Escalate PD Incident","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1250,400]}],"connections":{"Webhook":{"main":[[{"node":"Is Critical?","type":"main","index":0}]]},"Is Critical?":{"main":[[{"node":"Create PD Incident","type":"main","index":0}],[]]},"Create PD Incident":{"main":[[{"node":"Wait 30m for Ack","type":"main","index":0}]]},"Wait 30m for Ack":{"main":[[{"node":"Quantive Login","type":"main","index":0}]]},"Quantive Login":{"main":[[{"node":"Escalate in Quantive","type":"main","index":0},{"node":"Escalate PD Incident","type":"main","index":0}]]}}}
