$workflows["daily-compliance-digest"] = @'
{"name":"Quantive: Daily Compliance Digest","nodes":[{"parameters":{"rule":{"interval":1}},"id":"schedule","name":"Daily at 9AM","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1,"position":[250,300]},{"parameters":{"url":"http://localhost:4000/api/v1/auth/login","sendBody":true,"bodyParameters":{"parameters":[{"name":"email","value":"={{$parameter.quantiveEmail}}"},{"name":"password","value":"={{$parameter.quantivePassword}}"}],"options":{}},"options":{}},"id":"login","name":"Quantive Login","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[450,300]},{"parameters":{"url":"http://localhost:4000/api/v1/admin/dashboard","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{$json.data.accessToken}}"}],"options":{}},"options":{}},"id":"get-dash","name":"Get Dashboard","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[650,300]},{"parameters":{"url":"http://localhost:4000/api/v1/alerts","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{$json.data.accessToken}}"}],"options":{}},"options":{}},"id":"get-alerts","name":"Get Open Alerts","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[650,450]},{"parameters":{"url":"http://localhost:4000/api/v1/cases","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{$json.data.accessToken}}"}],"options":{}},"options":{}},"id":"get-cases","name":"Get Active Cases","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[650,600]},{"parameters":{"jsCode":"const dash=$input.all()[0].json.data;const alerts=$input.all()[1].json.data||[];const cases=$input.all()[2].json.data||[];const openAlerts=alerts.filter(a=>a.status==='OPEN');const critical=openAlerts.filter(a=>a.severity==='CRITICAL');const activeCases=cases.filter(c=>c.status==='OPEN'||c.status==='UNDER_REVIEW');return[{json:{date:new Date().toISOString().slice(0,10),totalTransactions:dash.overview.totalTransactions,openAlerts:dash.overview.openAlerts,criticalAlerts:critical.length,activeCases:dash.overview.activeCases,totalWallets:dash.overview.totalWallets,topAlerts:openAlerts.slice(0,5).map(a=>({title:a.title,severity:a.severity,reason:a.reasonCode}))}}]"},"id":"merge","name":"Build Digest","type":"n8n-nodes-base.code","typeVersion":2,"position":[850,300]},{"parameters":{"fromEmail":"quantive@localhost","toEmail":"={{$parameter.toEmail}}","subject":"=Quantive Daily Digest — {{$json.date}}","text":"=📊 QUANTIVE COMPLIANCE DIGEST — {{$json.date}}\n\n=== OVERVIEW ===\nTransactions: {{$json.totalTransactions}}\nOpen Alerts: {{$json.openAlerts}} ({{$json.criticalAlerts}} Critical)\nActive Cases: {{$json.activeCases}}\nWallets: {{$json.totalWallets}}\n\n=== TOP ALERTS ===\n{{$json.topAlerts.map(a=>'• ['+a.severity+'] '+a.title+' — '+a.reason).join('\\n')}}\n\nDashboard: http://localhost:3000","options":{}},"id":"email","name":"Send Email","type":"n8n-nodes-base.emailSend","typeVersion":1,"position":[1050,300]}],"connections":{"Daily at 9AM":{"main":[[{"node":"Quantive Login","type":"main","index":0}]]},"Quantive Login":{"main":[[{"node":"Get Dashboard","type":"main","index":0},{"node":"Get Open Alerts","type":"main","index":0},{"node":"Get Active Cases","type":"main","index":0}]]},"Get Dashboard":{"main":[[{"node":"Build Digest","type":"main","index":0}]]},"Get Open Alerts":{"main":[[{"node":"Build Digest","type":"main","index":0}]]},"Get Active Cases":{"main":[[{"node":"Build Digest","type":"main","index":0}]]},"Build Digest":{"main":[[{"node":"Send Email","type":"main","index":0}]]}}}
'@

