base.wait","typeVersion":1,"position":[850,750]},{"parameters":{"fromEmail":"onboarding@quantive.io","toEmail":"={{$node[\"New User Webhook\"].json.email}}","subject":"Quantive: API & Integration Guide","text":"=Hi {{$node[\"New User Webhook\"].json.name}},\n\nIntegrate Quantive with your tools:\n\n• REST API: http://localhost:4000/api/v1/docs\n• n8n workflows for automation\n• Webhook integration guide\n\n— The Quantive Team","options":{}},"id":"day7","name":"Day 7: Integration","type":"n8n-nodes-base.emailSend","typeVersion":1,"position":[1050,750]}],"connections":{"New User Webhook":{"main":[[{"node":"Day 0: Welcome","type":"main","index":0}]]},"Day 0: Welcome":{"main":[[{"node":"Wait 24h","type":"main","index":0}]]},"Wait 24h":{"main":[[{"node":"Day 1: Tip","type":"main","index":0}]]},"Day 1: Tip":{"main":[[{"node":"Wait 2d","type":"main","index":0}]]},"Wait 2d":{"main":[[{"node":"Day 3: Advanced","type":"main","index":0}]]},"Day 3: Advanced":{"main":[[{"node":"Wait 4d","type":"main","index":0}]]},"Wait 4d":{"main":[[{"node":"Day 7: Integration","type":"main","index":0}]]}}}
