$workflows["alert-escalation-path"] = @'
{"name":"Quantive: Alert Escalation Path","nodes":[{"parameters":{},"id":"webhook","name":"Webhook","type":"n8n-nodes-base.webhook","typeVersion":2,"position":[250,300],"webhookId":"quantive-escalation"},{"parameters":{"waitTime":"={{$parameter.ackTimeoutMin*60}}"},"id":"wait","name":"Wait for Ack","type":"n8n-nodes-base.wait","typeVersion":1,"position":[450,300]},{"parameters":{"url":"http://localhost:4000/api/v1/auth/login","sendBody":true,"bodyParameters":{"parameters":[{"name":"email","value":"={{$parameter.quantiveEmail}}"},{"name":"password","value":"={{$parameter.quantivePassword}}"}],"options":{}},"options":{}},"id":"login","name":"Quantive Login","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[650,300]},{"parameters":{"url":"=http://localhost:4000/api/v1/alerts/{{$node[\"Webhook\"].json.id}}","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{$json.data.accessToken}}"}],"options":{}},"options":{}},"id":"check-status","name":"Check Alert Status","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[850,300]},{"parameters":{"conditions":{"options":{"caseSensitive":true},"conditions":[{"id":"not-ack","leftValue":"={{$json.data.status}}","rightValue":"ACKNOWLEDGED","operator":{"type":"string","operation":"notEqual"}}],"combinator":"and"}},"id":"if-ack","name":"Was Acknowledged?","type":"n8n-nodes-base.if","typeVersion":2,"position":[1050,300]},{"parameters":{"url":"=http://localhost:4000/api/v1/alerts/{{$node[\"Webhook\"].json.id}}/status","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendBody":true,"method":"PATCH","bodyParameters":{"parameters":[{"name":"status","value":"ESCALATED"}],"options":{}},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{$json.data.accessToken}}"}],"options":{}},"options":{}},"id":"escalate","name":"Escalate Alert","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1250,200]},{"parameters":{"fromEmail":"escalations@quantive.io","toEmail":"={{$parameter.escalateTo}}","subject":"=Escalated: {{$node[\"Webhook\"].json.title}}","text":"=Alert {{$node[\"Webhook\"].json.id}} was not acknowledged within {{$parameter.ackTimeoutMin}} minutes and has been escalated.\n\nSeverity: {{$node[\"Webhook\"].json.severity}}\nDescription: {{$node[\"Webhook\"].json.description}}"},"id":"notify","name":"Notify Escalation Contact","type":"n8n-nodes-base.emailSend","typeVersion":1,"position":[1250,400]}],"connections":{"Webhook":{"main":[[{"node":"Wait for Ack","type":"main","index":0}]]},"Wait for Ack":{"main":[[{"node":"Quantive Login","type":"main","index":0}]]},"Quantive Login":{"main":[[{"node":"Check Alert Status","type":"main","index":0}]]},"Check Alert Status":{"main":[[{"node":"Was Acknowledged?","type":"main","index":0}]]},"Was Acknowledged?":{"main":[[{"node":"Escalate Alert","type":"main","index":0},{"node":"Notify Escalation Contact","type":"main","index":0}],[]]}}}
